\label{lem:nilp-crit}
For a nilpotent endomorphism $x \in \mathcal{N}_V$, the following conditions are equivalent:
\begin{enumerate}
\item $x \in \overline{\mathcal{O}_\lambda}$.
\item The Jordan type $\rho$ of $x$ satisfies $\rho\leq\lambda$.
\item $V$ admits a filtration $0 = V_0 \subset V_1 \subset \cdots \subset V_{\lambda_1} = V$ such that $x(V_i) \subset V_{i-1}$ and $\dim V_i/V_{i-1} = \lambda^{\mathbf{t}}_{\lambda_1+1-i}$.
\item $V$ admits a filtration $0 = V_0 \subset V_1 \subset \cdots \subset V_{\lambda_1} = V$ such that $x(V_i) \subset V_{i-1}$ and $\dim V_i/V_{i-1} = \lambda^{\mathbf{t}}_{i}$.
\end{enumerate}

\begin{equation} \label{eqn:bipartitionsum}
\bar\pi^V(\mathcal{O}_{\mu;\nu}) = \mathcal{O}_{\mu+\nu}.
\end{equation}

\label{lem:enhcl-crit}
For $(v,x) \in V \times \mathcal{N}_V$, the following conditions are equivalent:
\begin{enumerate}
\item $(v,x) \in \overline{\mathcal{O}_{\mu;\nu}}$.
\item The type $(\rho;\sigma)$ of $(v,x)$ satisfies $(\rho;\sigma)\leq(\mu;\nu)$.
\item There is an $x$-stable $|\mu|$-dimensional subspace $W \subset V$ containing $v$ such that 
\begin{enumerate}
\item the Jordan type $\bar\mu$ of $x|_W$ satisfies $\bar\mu \le \mu$, and
\item the Jordan type $\bar\nu$ of $x|_{V/W}$ satisfies $\bar\nu \le \nu$.
\end{enumerate}
\end{enumerate}

