\mathrm{codim}_{\Lambda_{(r_i),I}}\,\Lambda^{\xi}_{(r_i),I}\geq\frac{1}{2}\mathrm{codim}_{\overline{\mathcal{O}_{\mu;\nu}}}\,\Phi(\Lambda^{\xi}_{(r_i),I}),
\end{equation}

Continue with Example~\ref{exam:strata}. There is a stratum $\Lambda_{(1,1,2),\{0,2\}}^\xi$ consisting of all tuples $(u_i,A_i,B_i)$ such that $u_1\neq 0$, $A_1=0$, $B_1\neq 0$, $A_2$ is injective, and $B_2$ is surjective. The corresponding signed quasibipartitions are as follows:
